	policy: 'declared-file-input-surfaces-only';
	rule: typeof WITNESS_FILE_INPUT_LOAD_RULE;
	declared: WitnessFileInputSurfaceEntry[];
	loaded: WitnessFileInputLoadEntry[];
	unused: WitnessFileInputSurfaceEntry[];
	outsideDeclaration: [];
};

